    "explanation": "**[풀이]**\n\n**[핵심 개념]:** $\\frac{0}{0}$ 부정형이 나오면 인수분해를 통해 공통인수를 약분한다. $x^2 - 9 = (x-3)(x+3)$처럼 합차공식을 활용하면, 분모와 공통인수를 소거할 수 있다.\n\n**Step 1.** $x = 3$을 대입하면 $\\frac{0}{0}$ 부정형이므로 분자를 인수분해한다.\n$x^2 - 9 = (x-3)(x+3)$\n\n**Step 2.** 공통인수 $(x-3)$을 약분한다.\n$\\dfrac{(x-3)(x+3)}{x-3} = x + 3$\n\n**Step 3.** $x \\to 3$을 대입한다.\n$x + 3 \\to 3 + 3 = 6$\n\n**∴ 답: ② $6$**\n\n① $3$: 약분 후 $x+3$에서 $+3$을 빠뜨리고 $x=3$만 답한 경우이다.\n③ $9$: $x^2-9$에서 $x=3$ 대입 시 $9-9=0$이 아니라 $x^2=9$로 혼동한 경우이다.\n④ $0$: 부정형을 해결하지 않고 분자에 직접 대입한 경우이다.\n⑤ $-6$: 부호를 잘못 처리한 경우이다.\n\n**💡 포인트:** $\\frac{0}{0}$ 부정형에서는 반드시 인수분해 후 약분하여 극한을 구한다.",
