    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 절댓값 함수의 극한에서는 좌극한과 우극한을 각각 구해야 한다. $|x| = x$ ($x > 0$), $|x| = -x$ ($x < 0$)이므로, $x \\to 0$ 양쪽에서 함수의 행동이 다릅니다. 극한이 존재하려면 좌극한 = 우극한이어야 한다.\n\n**Step 1.** 우극한을 구한다. $x > 0$일 때 $|x| = x$이므로\n$\\lim_{x \\to 0^+}\\dfrac{|x|}{x} = \\lim_{x \\to 0^+}\\dfrac{x}{x} = 1$\n\n**Step 2.** 좌극한을 구한다. $x < 0$일 때 $|x| = -x$이므로\n$\\lim_{x \\to 0^-}\\dfrac{|x|}{x} = \\lim_{x \\to 0^-}\\dfrac{-x}{x} = -1$\n\n**Step 3.** 좌극한 $= -1 \\neq 1 =$ 우극한이므로 극한값이 존재하지 않는다.\n\n**∴ 답: ④ 극한값이 존재하지 않는다**\n\n① $1$: 우극한만 고려한 경우이다.\n② $-1$: 좌극한만 고려한 경우이다.\n③ $0$: 좌극한과 우극한의 평균을 취한 오류이다.\n⑤ $\\infty$: 분모가 0에 가까워진다고 발산한다고 오해한 경우이다.\n\n**💡 포인트:** 절댓값이 포함된 극한은 반드시 좌극한과 우극한을 따로 조사해야 한다.",
