    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 가우스 함수(바닥함수) $[x]$는 $x$를 넘지 않는 최대 정수이다. 정수 점에서 좌극한과 우극한이 달라지므로, 정수에서는 극한이 존재하지 않는다.\n\n**Step 1.** 우극한을 구한다. $x \\to 0^+$이면 $0 < x < 1$이므로\n$[x] = 0$, 따라서 $\\lim_{x \\to 0^+}[x] = 0$\n\n**Step 2.** 좌극한을 구한다. $x \\to 0^-$이면 $-1 < x < 0$이므로\n$[x] = -1$, 따라서 $\\lim_{x \\to 0^-}[x] = -1$\n\n**Step 3.** 좌극한 $= -1 \\neq 0 =$ 우극한이므로 극한이 존재하지 않는다.\n\n**∴ 답: ④ 극한값이 존재하지 않는다**\n\n① $0$: 우극한만 고려한 경우이다.\n② $-1$: 좌극한만 고려한 경우이다.\n③ $1$: $[x]$의 정의를 잘못 이해한 경우이다.\n⑤ $\\dfrac{1}{2}$: 좌극한과 우극한의 평균을 취한 오류이다.\n\n**💡 포인트:** 가우스 함수는 모든 정수 점에서 좌극한 ≠ 우극한이므로 극한이 존재하지 않는다.",
