    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 분자·분모 모두 무리식이면 각각 유리화하여 $\\frac{0}{0}$을 해결한다. 분자·분모에 각각의 켤레식을 곱하는 방법이 효과적이다.\n\n**Step 1.** 분자·분모를 동시에 유리화한다.\n$\\dfrac{\\sqrt{2x-1}-1}{\\sqrt{3x-2}-1} \\cdot \\dfrac{\\sqrt{3x-2}+1}{\\sqrt{3x-2}+1} \\cdot \\dfrac{\\sqrt{2x-1}+1}{\\sqrt{2x-1}+1}$\n\n정리하면: $\\dfrac{(2x-1)-1}{(3x-2)-1} \\cdot \\dfrac{\\sqrt{3x-2}+1}{\\sqrt{2x-1}+1} = \\dfrac{2(x-1)}{3(x-1)} \\cdot \\dfrac{\\sqrt{3x-2}+1}{\\sqrt{2x-1}+1}$\n\n**Step 2.** $(x-1)$을 약분한다.\n$= \\dfrac{2}{3} \\cdot \\dfrac{\\sqrt{3x-2}+1}{\\sqrt{2x-1}+1}$\n\n**Step 3.** $x \\to 1$을 대입한다.\n$= \\dfrac{2}{3} \\cdot \\dfrac{1+1}{1+1} = \\dfrac{2}{3} \\cdot 1 = \\dfrac{2}{3}$\n\n**∴ 답: ② $\\dfrac{2}{3}$**\n\n① $\\dfrac{1}{3}$: 분자의 계수 $2$를 빠뜨린 경우이다.\n③ $1$: 비율 계산을 생략한 경우이다.\n④ $\\dfrac{3}{2}$: 분자와 분모를 바꾼 경우이다.\n⑤ $3$: 계산 오류이다.\n\n**💡 포인트:** $\\frac{\\sqrt{ax+b}-c}{\\sqrt{dx+e}-f}$ 형태에서는 각각 유리화하여 $\\frac{a}{d}$의 비율을 구한다.",
