    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 이중 유리화가 필요한 고난이도 문제이다. $\\sqrt{1+x}+\\sqrt{1-x}-2$에서 $A = \\sqrt{1+x}-1$, $B = \\sqrt{1-x}-1$로 분리한다.\n\n**Step 1.** $\\sqrt{1+x}-1$과 $\\sqrt{1-x}-1$을 각각 유리화한다.\n$\\sqrt{1+x}-1 = \\dfrac{x}{\\sqrt{1+x}+1}$, $\\sqrt{1-x}-1 = \\dfrac{-x}{\\sqrt{1-x}+1}$\n\n**Step 2.** 합산한다.\n$\\dfrac{x}{\\sqrt{1+x}+1} + \\dfrac{-x}{\\sqrt{1-x}+1} = x\\left(\\dfrac{1}{\\sqrt{1+x}+1} - \\dfrac{1}{\\sqrt{1-x}+1}\\right)$\n\n**Step 3.** 통분하여 정리하면\n$= x \\cdot \\dfrac{(\\sqrt{1-x}+1)-(\\sqrt{1+x}+1)}{(\\sqrt{1+x}+1)(\\sqrt{1-x}+1)} = x \\cdot \\dfrac{\\sqrt{1-x}-\\sqrt{1+x}}{(\\sqrt{1+x}+1)(\\sqrt{1-x}+1)}$\n\n분자의 $\\sqrt{1-x}-\\sqrt{1+x}$를 유리화: $\\frac{-2x}{\\sqrt{1-x}+\\sqrt{1+x}}$\n\n따라서 전체 = $\\frac{-2x^2}{(\\sqrt{1+x}+1)(\\sqrt{1-x}+1)(\\sqrt{1-x}+\\sqrt{1+x})}$\n\n$x^2$로 나누면: $\\frac{-2}{(\\sqrt{1+x}+1)(\\sqrt{1-x}+1)(\\sqrt{1-x}+\\sqrt{1+x})} \\to \\frac{-2}{2 \\cdot 2 \\cdot 2} = -\\frac{1}{4}$\n\n**∴ 답: ① $-\\dfrac{1}{4}$**\n\n② $-\\dfrac{1}{2}$: 이중 유리화에서 일부 계수를 빠뜨린 경우이다.\n③ $0$: 대칭성 때문에 상쇄된다고 오판한 경우이다.\n④ $\\dfrac{1}{4}$: 부호를 잘못 처리한 경우이다.\n⑤ $\\dfrac{1}{2}$: 계산 오류이다.\n\n**💡 포인트:** 이중 유리화는 고난이도 문제에서 필수적인 기법이다.",
