    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 분모의 차수가 분자의 차수보다 크면 극한값은 $0$이다. 분자는 $x^2$ (2차), 분모는 $x^3$ (3차)이므로 분모가 훨씬 빨리 증가한다.\n\n**Step 1.** 분자·분모를 $x^3$ (최고차)으로 나눕니다.\n$\\dfrac{x^2+1}{x^3+1} = \\dfrac{\\frac{1}{x}+\\frac{1}{x^3}}{1+\\frac{1}{x^3}}$\n\n**Step 2.** $x \\to \\infty$이면 $\\frac{1}{x} \\to 0$, $\\frac{1}{x^3} \\to 0$이므로\n$\\dfrac{0+0}{1+0} = 0$\n\n**∴ 답: ① $0$**\n\n② $1$: 계수비를 $1$로 잘못 계산한 경우이다.\n③ $\\infty$: 분자 차수 > 분모 차수인 경우와 혼동한 것이다.\n④ $-1$: 부호 오류이다.\n⑤ $\\dfrac{1}{2}$: 계산 오류이다.\n\n**💡 포인트:** (분자 차수) < (분모 차수)이면 $\\to 0$, 같으면 계수비, 크면 $\\to \\pm\\infty$이다.",
