    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 유리함수 $\\dfrac{P(x)}{Q(x)}$에서 $x \\to \\infty$일 때, 분자의 최고차항 차수가 분모의 최고차항 차수보다 크면 극한값은 $\\pm\\infty$이다. 분자 차수 = 분모 차수이면 최고차항의 계수비가 극한값이 되고, 분자 차수 < 분모 차수이면 극한값은 $0$이다.\n\n**Step 1.** 분자와 분모의 최고차항 차수를 비교한다.\n분자: $2x^3$ (3차), 분모: $3x^2$ (2차)\n분자 차수($3$) > 분모 차수($2$)\n\n**Step 2.** 분자 차수가 분모 차수보다 크므로 $x \\to \\infty$일 때 식의 값은 $\\infty$로 발산한다.\n$\\dfrac{2x^3-x+1}{3x^2+5} = \\dfrac{x^2(2-\\frac{1}{x^2}+\\frac{1}{x^3})}{x^2(3+\\frac{5}{x^2})} \\cdot x \\to \\dfrac{2}{3} \\cdot x \\to \\infty$\n\n**∴ 답: ④ $\\infty$**\n\n① $0$: 분자 차수가 분모 차수보다 작을 때의 결과이다.\n② $\\dfrac{2}{3}$: 분자 차수와 분모 차수가 같다고 착각한 경우이다.\n③ $\\dfrac{3}{2}$: 계수비를 뒤집어 구한 경우이다.\n⑤ $-\\infty$: 최고차 계수가 모두 양수이므로 $+\\infty$가 맞다.\n\n**💡 포인트:** 유리함수의 극한에서 가장 먼저 분자·분모의 최고차항 차수를 비교하는 것이 핵심이다.",
