    "explanation": "**[풀이]**\n\n**[핵심 개념]:** $\\sqrt{A}-\\sqrt{B}$ 꼴의 $\\infty - \\infty$ 부정형은 유리화하여 $\\dfrac{A-B}{\\sqrt{A}+\\sqrt{B}}$로 변환한다.\n\n**Step 1.** 유리화한다.\n$\\dfrac{(x^2+2x+3)-(x^2-2x+3)}{\\sqrt{x^2+2x+3}+\\sqrt{x^2-2x+3}} = \\dfrac{4x}{\\sqrt{x^2+2x+3}+\\sqrt{x^2-2x+3}}$\n\n**Step 2.** $x$로 나눕니다 ($x > 0$).\n$= \\dfrac{4}{\\sqrt{1+\\frac{2}{x}+\\frac{3}{x^2}}+\\sqrt{1-\\frac{2}{x}+\\frac{3}{x^2}}} \\to \\dfrac{4}{1+1} = 2$\n\n**∴ 답: ③ $2$**\n\n① $0$: 두 제곱근이 상쇄된다고 착각한 경우이다.\n② $1$: 분모를 $4$로 잘못 계산한 경우이다.\n④ $3$: 상수항을 포함하여 계산한 경우이다.\n⑤ $4$: 분모의 $+\\sqrt{\\cdots}$ 부분을 빠뜨린 경우이다.\n\n**💡 포인트:** 두 제곱근의 차에서는 유리화 후 분자에 일차항 차이($4x$)만 남고, 분모는 $2x$로 근사된다.",
