    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 고정점(부동점) 정리: $f: [0,1] \\to [0,1]$이 연속이면 $f(c) = c$인 고정점 $c$가 존재한다. 이를 증명하기 위해 보조함수 $g(x) = f(x) - x$를 정의한다.\n\n**Step 1.** $g(x) = f(x) - x$로 정의한다.\n\n**Step 2.** 양 끝점의 부호를 확인한다.\n$g(0) = f(0) - 0 = f(0) \\geq 0$ ($f: [0,1] \\to [0,1]$이므로 $f(0) \\geq 0$)\n$g(1) = f(1) - 1 \\leq 0$ ($f(1) \\leq 1$이므로)\n\n**Step 3.** $g(0) \\geq 0$이고 $g(1) \\leq 0$이므로\n사잇값의 정리에 의해 $g(c) = 0$, 즉 $f(c) = c$인 $c \\in [0,1]$이 존재한다.\n\n**∴ 답: ② $f(x)-x$**\n\n① $f(x)+x$: 이 함수의 영점은 $f(c) = -c$이므로 고정점이 아닙니다.\n③ $f(x) \\cdot x$: 영점이 $f(c) = 0$ 또는 $c = 0$이므로 고정점과 무관한다.\n④ $f(x)/x$: $x = 0$에서 정의되지 않는다.\n⑤ $f(x)^2$: 고정점과 무관한다.\n\n**💡 포인트:** $f(c) = c$ iff $f(c) - c = 0$ iff $g(c) = 0$이므로 $g(x) = f(x) - x$를 보조함수로 사용한다.",
