    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 미정계수 결정 (분수함수의 극한) — $\\lim_{x \\to c} \\dfrac{f(x)}{g(x)}$에서 $g(c) = 0$이면, 극한이 존재하려면 반드시 $f(c) = 0$이어야 한다 (그렇지 않으면 $\\pm\\infty$로 발산). 이 조건으로 미지수를 결정한다.\n\n**Step 1.** $x \\to 1$일 때 분모 $x - 1 \\to 0$이므로, 극한이 존재하려면 분자도 $0$이어야 한다.\n$f(1) = 1 + a - 2 = a - 1 = 0$\n\n**Step 2.** $a = 1$\n\n**Step 3.** 검증: $a = 1$이면 $\\dfrac{x^2 + x - 2}{x - 1} = \\dfrac{(x-1)(x+2)}{x-1} = x + 2 \\to 3$ (극한 존재 확인)\n\n**∴ 답: ③ $1$**\n\n① $a = -1$: $f(1) = 1 - 1 - 2 = -2 \\neq 0$이므로 극한이 발산한다.\n② $a = 0$: $f(1) = 1 + 0 - 2 = -1 \\neq 0$이므로 극한이 발산한다.\n④ $a = 2$: $f(1) = 1 + 2 - 2 = 1 \\neq 0$이므로 극한이 발산한다.\n⑤ $a = 3$: $f(1) = 1 + 3 - 2 = 2 \\neq 0$이므로 극한이 발산한다.\n\n**💡 포인트:** 분모 → 0이면 극한이 존재하기 위해 분자 → 0 (필요조건). 이것이 미정계수 결정의 기본 원리이다.",
