    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 접선의 기울기 — 곡선 $y = f(x)$ 위의 점 $(a, f(a))$에서의 접선의 기울기는 $f'(a)$이다. 미분계수가 곧 접선의 기울기이다.\n\n**Step 1.** $f(x) = x^3 - 2x$를 미분한다.\n$f'(x) = 3x^2 - 2$\n\n**Step 2.** $x = 1$에서의 미분계수(접선 기울기):\n$f'(1) = 3(1)^2 - 2 = 3 - 2 = 1$\n\n(검증: $f(1) = 1 - 2 = -1$이므로 점 $(1, -1)$은 곡선 위에 있다 ✓)\n\n**∴ 답: ③ $1$**\n\n① $-1$: $f(1) = -1$과 혼동한 경우이다.\n② $0$: $f'(x) = 0$의 근과 혼동한 경우이다.\n④ $2$: $f'(x)$에서 $-2$를 빼지 않은 경우이다.\n⑤ $3$: $3x^2$에서 $x = 1$만 대입한 경우이다.\n\n**💡 포인트:** 접선의 기울기 = $f'(a)$. 다항함수의 미분은 $x^n \\to nx^{n-1}$이다.",
