    "explanation": "**[풀이]**\n\n**[핵심 개념]:** $\\dfrac{\\sin u}{u} \\to 1$ ($u \\to 0$)을 활용한 극한 — $x \\to 2$이면 $x^2 - 4 \\to 0$이므로, $\\sin(x^2-4) \\approx x^2 - 4$로 근사할 수 있다.\n\n**Step 1.** $\\dfrac{\\sin(x^2-4)}{x-2} = \\dfrac{\\sin(x^2-4)}{x^2-4} \\cdot \\dfrac{x^2-4}{x-2}$\n\n**Step 2.** $x \\to 2$이면 $x^2 - 4 \\to 0$이므로 $\\dfrac{\\sin(x^2-4)}{x^2-4} \\to 1$\n\n**Step 3.** $\\dfrac{x^2-4}{x-2} = \\dfrac{(x-2)(x+2)}{x-2} = x+2 \\to 4$\n\n**Step 4.** $\\lim = 1 \\times 4 = 4$이므로 $k = 4$\n\n**∴ 답: ③ $4$**\n\n① $0$: $\\sin(0) = 0$이지만 $\\dfrac{0}{0}$ 부정형의 극한은 $0$이 아닙니다.\n② $2$: $x + 2$에서 $x = 2$가 아닌 $x = 0$을 대입한 경우이다.\n④ $\\sin 4$: $\\sin(x^2-4)$에서 직접 $\\sin 4$를 구한 경우(잘못된 접근)이다.\n⑤ $4\\cos 4$: 로피탈 정리를 잘못 적용한 경우이다.\n\n**💡 포인트:** $\\dfrac{\\sin u}{v}$에서 $u, v \\to 0$이면 $\\dfrac{\\sin u}{u} \\cdot \\dfrac{u}{v}$로 분해하여 $\\dfrac{\\sin u}{u} \\to 1$을 활용한다.",
