    "explanation": "**[풀이]**\n\n**[핵심 개념]:** $0^0$ 부정형 — $x \\to 0^+$일 때 밑 $x \\to 0$이고 지수 $x \\to 0$이므로 $0^0$ 부정형이다. $x^x = e^{x \\ln x}$로 변환하여 $x \\ln x$의 극한을 조사한다.\n\n**Step 1.** $x^x = e^{x \\ln x}$\n\n**Step 2.** $\\lim_{x \\to 0^+} x \\ln x$를 구한다.\n$x \\ln x = \\dfrac{\\ln x}{1/x}$ ($\\dfrac{-\\infty}{\\infty}$ 부정형)\n\n로피탈 정리: $\\dfrac{(\\ln x)'}{(1/x)'} = \\dfrac{1/x}{-1/x^2} = -x \\to 0$\n\n**Step 3.** $\\lim_{x \\to 0^+} x \\ln x = 0$\n\n**Step 4.** $\\lim_{x \\to 0^+} x^x = e^0 = 1$\n\n**∴ 답: ③ $1$**\n\n① $0$: $0^0$은 $0$이 아닙니다.\n② $1/e$: $x\\ln x$의 극한이 $-1$이 아닌 $0$이다.\n④ $e$: $x\\ln x$의 극한이 $1$이 아닌 $0$이다.\n⑤ 존재하지 않는다: 극한은 존재하며 $1$이다.\n\n**💡 포인트:** $0^0$ 부정형은 $e^{x\\ln x}$로 변환한다. $x\\ln x \\to 0$ ($x \\to 0^+$)은 로피탈이나 치환($t = -\\ln x$)으로 증명한다.",
