    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 쌍곡선 함수와 테일러 전개 — $e^x + e^{-x} = 2\\cosh x$이다. 테일러 전개를 이용하면 $e^x = 1 + x + \\dfrac{x^2}{2} + \\cdots$, $e^{-x} = 1 - x + \\dfrac{x^2}{2} + \\cdots$이므로 합은 $2 + x^2 + \\cdots$이다.\n\n**Step 1.** 테일러 전개를 적용한다.\n$e^x = 1 + x + \\dfrac{x^2}{2} + \\dfrac{x^3}{6} + \\cdots$\n$e^{-x} = 1 - x + \\dfrac{x^2}{2} - \\dfrac{x^3}{6} + \\cdots$\n\n**Step 2.** 합을 구한다.\n$e^x + e^{-x} = 2 + x^2 + \\dfrac{x^4}{12} + \\cdots$\n$e^x + e^{-x} - 2 = x^2 + \\dfrac{x^4}{12} + \\cdots$\n\n**Step 3.** $x^2$으로 나눕니다.\n$\\dfrac{x^2 + x^4/12 + \\cdots}{x^2} = 1 + \\dfrac{x^2}{12} + \\cdots \\to 1$\n\n**∴ 답: ③ $1$**\n\n① $0$: 분자의 주항이 $x^2$이므로 극한은 $0$이 아닙니다.\n② $\\dfrac{1}{2}$: $\\dfrac{1-\\cos x}{x^2} \\to \\dfrac{1}{2}$와 혼동한 경우이다.\n④ $\\dfrac{3}{2}$: 다른 극한과 혼동한 경우이다.\n⑤ $2$: $e^x - 1$과 $1 - e^{-x}$를 각각 $1$로 놓은 경우이다.\n\n**💡 포인트:** $e^x + e^{-x} - 2 \\approx x^2$이므로 $\\dfrac{e^x + e^{-x} - 2}{x^2} \\to 1$. 이는 $\\cosh x - 1 \\approx \\dfrac{x^2}{2}$의 $2$배이다.",
