    "explanation": "**[풀이]**\n\n**[핵심 개념]:** 무리식의 비의 극한 — 분자·분모를 각각 유리화하거나, $\\sqrt{1+u} - 1 \\approx \\dfrac{u}{2}$ ($u \\to 0$)의 근사를 이용한다.\n\n**Step 1.** 선형 근사를 적용한다.\n$\\sqrt{1+3x} - 1 \\approx \\dfrac{3x}{2}$\n$\\sqrt{1+5x} - 1 \\approx \\dfrac{5x}{2}$\n\n**Step 2.** 비를 구한다.\n$\\dfrac{3x/2}{5x/2} = \\dfrac{3}{5}$\n\n**[유리화 풀이 (검증)]:**\n$\\dfrac{\\sqrt{1+3x}-1}{\\sqrt{1+5x}-1} = \\dfrac{(\\sqrt{1+3x}-1)(\\sqrt{1+5x}+1)}{(\\sqrt{1+5x}-1)(\\sqrt{1+5x}+1)} \\cdot \\dfrac{\\sqrt{1+3x}+1}{\\sqrt{1+3x}+1}$\n\n유리화하면: $\\dfrac{3x(\\sqrt{1+5x}+1)}{5x(\\sqrt{1+3x}+1)} = \\dfrac{3(\\sqrt{1+5x}+1)}{5(\\sqrt{1+3x}+1)} \\to \\dfrac{3 \\cdot 2}{5 \\cdot 2} = \\dfrac{3}{5}$\n\n**∴ 답: ② $\\dfrac{3}{5}$**\n\n① $\\dfrac{1}{5}$: 분자의 $3$을 무시한 경우이다.\n③ $1$: 두 무리식의 계수 차이를 무시한 경우이다.\n④ $\\dfrac{5}{3}$: 분자와 분모를 바꾼 경우이다.\n⑤ $5$: $\\dfrac{5x}{x} = 5$로 잘못 계산한 경우이다.\n\n**💡 포인트:** $\\dfrac{\\sqrt{1+ax}-1}{\\sqrt{1+bx}-1} \\to \\dfrac{a}{b}$ ($x \\to 0$). 무리식 비의 극한은 계수의 비와 같다.",
